/**
 * ---- Responsive sizing note ---------------------------------------------
 * Every clamp() below is (min, preferred-vw, max). Only the MIN values
 * were lowered here so icons/pills/text can keep shrinking on small
 * screens instead of hitting a floor and overlapping. The preferred vw
 * value and the max are untouched, so nothing changes on desktop —
 * this only takes effect once the viewport gets narrow enough that the
 * old minimum used to kick in.
 */

function ToolIcon({ tool }) {
  return (
    <div
      className="
        flex
        size-[clamp(14px,2.9vw,37px)]
        shrink-0
        items-center
        justify-center
        rounded-[clamp(6px,1vw,13px)]
        border border-white/[0.10]
        bg-[#ffffff0d]
      "
      aria-label={tool}
    >
      <img
        src={TOOLS[tool]}
        alt=""
        loading="lazy"
        className="size-[clamp(8px,1.55vw,20px)] object-contain"
      />
    </div>
  )
}

function PersonNode({ person }) {
  return (
    <div
      className="
        absolute
        z-10
        flex
        -translate-x-1/2
        flex-col
        items-center
      "
      style={{
        left: `${person.x}%`,
        top: `${person.y}%`,
      }}
    >
      <div className="flex gap-[clamp(2px,0.8vw,10px)]">
        {person.tools.map((tool) => (
          <ToolIcon key={tool} tool={tool} />
        ))}
      </div>

      <div
        className="
          mt-[clamp(4px,1.72vw,22px)]
          flex
          h-[clamp(20px,3.9vw,50px)]
          min-w-[clamp(46px,10.5vw,134px)]
          items-center
          rounded-full
          border border-white/[0.11]
          bg-[#111111]
          pl-[clamp(2px,0.6vw,8px)]
          pr-[clamp(4px,1.3vw,17px)]
        "
      >
        <div
          className="
            flex
            size-[clamp(14px,2.35vw,30px)]
            shrink-0
            items-center
            justify-center
            rounded-full
            border border-white/[0.10]
            bg-[#ffffff0d]
            text-[clamp(6px,0.95vw,12px)]
            font-medium
            text-white/60
          "
        >
          {person.initials}
        </div>

        <div className="ml-[clamp(3px,0.85vw,11px)] min-w-0 leading-none">
          <p className="whitespace-nowrap text-[clamp(6px,1.1vw,14px)] font-medium text-white/90">
            {person.name}
          </p>

          <p className="mt-[clamp(1px,0.45vw,6px)] whitespace-nowrap text-[clamp(5px,0.85vw,12px)] text-white/35">
            {person.role}
          </p>
        </div>
      </div>
    </div>
  )
}

function ConnectorNetwork() {
  return (
    <svg
      viewBox="0 0 1200 493"
      preserveAspectRatio="none"
      className="
        pointer-events-none
        absolute
        inset-0
        z-0
        size-full
      "
      aria-hidden="true"
    >
      {PEOPLE.map((person, index) => (
        <g key={person.name}>
          <path
            d={person.connector}
            fill="none"
            stroke="rgba(255,255,255,0.11)"
            strokeWidth="1.25"
            vectorEffect="non-scaling-stroke"
          />

          <circle
            r="2.8"
            fill="#e7bd6a"
            className="drop-shadow-[0_0_4px_rgba(231,189,106,0.55)]"
          >
            <animateMotion
              dur={`${2.5 + index * 0.12}s`}
              begin={`${index * 0.35}s`}
              repeatCount="indefinite"
              path={person.connector}
            />
          </circle>
        </g>
      ))}
    </svg>
  )
}

function AgentIcon({ agent }) {
  return (
    <div
      className="
        flex
        size-[clamp(18px,3.6vw,49px)]
        shrink-0
        items-center
        justify-center
        rounded-[clamp(6px,1.1vw,14px)]
        border border-white/[0.10]
        bg-[#171717]
      "
      aria-label={agent.name}
    >
      <img
        src={agent.logo}
        alt=""
        loading="lazy"
        className="size-[clamp(11px,2.2vw,30px)] object-contain"
      />
    </div>
  )
}

export default function OrgChart() {
  return (
    <section className="flex w-full justify-center bg-[#0d0d0d]">
      <div
        className="
          relative
          aspect-[2048/841]
          w-full
          max-w-[1280px]
          overflow-hidden
        "
      >
        {/* Network */}
        <ConnectorNetwork />

        {/* People */}
        {PEOPLE.map((person) => (
          <PersonNode key={person.name} person={person} />
        ))}

        {/* AI / Agent group */}
        <div
          className="
            absolute
            left-1/2
            top-[76.8%]
            z-20
            flex
            h-[clamp(28px,5.1vw,70px)]
            w-[clamp(120px,20.5vw,280px)]
            -translate-x-1/2
            items-center
            justify-center
            rounded-[clamp(8px,1.7vw,23px)]
            border border-white/[0.11]
            bg-[#171717]
          "
        >
          <div className="flex gap-[clamp(3px,0.95vw,13px)]">
            {AGENTS.map((agent) => (
              <AgentIcon key={agent.name} agent={agent} />
            ))}
          </div>
        </div>

        {/* Caption */}
      <p
  className="
    max-sm:hidden
    absolute
    left-0
    right-0
    top-[95.6%]
    z-20
    px-4
    text-center
    text-[clamp(8px,1.1vw,14px)]
    leading-none
    text-white/35
  "
>
  Every agent reads the same context. Each person's stays their own.
</p>
      </div>
    </section>
  )
}